{"type":"item.completed","item":{"id":"item_1","type":"agent_message","text":"{\"tool\":\"sql_query\",\"arguments\":{\"company_name\":\"CLOSE_fin_05\",\"table_name\":\"ledger\",\"query\":\"WITH eligible AS (SELECT kind,event_key,invoice_id,vendor,business_date,recorded_at,revision,status,amount_minor,currency,due_date,discount_until,terms_code,discount_bps,fx_num,fx_den FROM ledger WHERE date(business_date)<=date('2026-10-23') AND datetime(recorded_at)<=datetime('2026-10-24 12:00:00')), ranked AS (SELECT kind,event_key,invoice_id,vendor,business_date,revision,status,amount_minor,currency,due_date,discount_until,terms_code,discount_bps,fx_num,fx_den,ROW_NUMBER() OVER(PARTITION BY kind,event_key ORDER BY revision DESC) rn FROM eligible), latest AS (SELECT kind,event_key,invoice_id,vendor,business_date,status,amount_minor,currency,due_date,discount_until,terms_code,discount_bps,fx_num,fx_den FROM ranked WHERE rn=1 AND status<>'void'), invoices AS (SELECT event_key,business_date,currency,discount_until,terms_code,amount_minor FROM latest WHERE kind='invoice' AND status='active' AND vendor='BLUE' AND date(due_date)<=date('2026-10-30')), payments AS (SELECT invoice_id,SUM(amount_minor) amount FROM latest WHERE kind='payment' AND status='active' GROUP BY invoice_id), credits AS (SELECT invoice_id,SUM(amount_minor) amount FROM latest WHERE kind='credit' AND status='active' GROUP BY invoice_id), holds AS (SELECT invoice_id,SUM(amount_minor) amount FROM latest WHERE kind='hold' AND status NOT IN('release','void') GROUP BY invoice_id), amounts AS (SELECT i.event_key,i.business_date,i.currency,i.discount_until,i.terms_code,MAX(0,i.amount_minor-COALESCE(p.amount,0)-COALESCE(c.amount,0)) remaining,COALESCE(h.amount,0) held FROM invoices i LEFT JOIN payments p ON p.invoice_id=i.event_key LEFT JOIN credits c ON c.invoice_id=i.event_key LEFT JOIN holds h ON h.invoice_id=i.event_key), selected AS (SELECT a.event_key,MAX(0,a.remaining-a.held) unheld,CASE WHEN date('2026-10-23')<=date(